typedef unsigned char u8;typedef unsigned short u16;typedef unsigned u32;typedef unsigned long u64;
int file_utf8(const u8*p,u32 n){u32 i=0;while(i<n){u8 f=p[i++];u32 c,m,r;if(f<=0x7f)continue;if(f>=0xc2&&f<=0xdf)c=f&31,m=0x80,r=1;else if(f>=0xe0&&f<=0xef)c=f&15,m=0x800,r=2;else if(f>=0xf0&&f<=0xf4)c=f&7,m=0x10000,r=3;else return 0;if(r>n-i)return 0;while(r--){u8 q=p[i++];if((q&0xc0)!=0x80)return 0;c=(c<<6)|(q&63);}if(c<m||c>0x10ffff||(c>=0xd800&&c<=0xdfff))return 0;}return 1;}int file_path_valid(const u8*p,u32 n){return p&&n&&n<=FILE_MAX_PATH_LENGTH&&file_utf8(p,n);}struct file files[FILE_MAX_COUNT];u32 file_count;static void cp(u8*d,const u8*s,u32 n){for(u32 i=0;i<n;++i)d[i]=s[i];}static void cpf(struct file*d,const struct file*s){cp(d->path,s->path,s->path_length);d->path_length=s->path_length;d->content=s->content;d->content_length=s->content_length;d->content_capacity=s->content_capacity;d->attributes=s->attributes;}static int eq(const u8*a,u32 n,const u8*b,u32 m){if(n!=m)return 0;for(u32 i=0;i<n;++i)if(a[i]!=b[i])return 0;return 1;}static int cmp(const u8*a,u32 n,const u8*b,u32 m){u32 z=n<m?n:m;for(u32 i=0;i<z;++i){if(a[i]<b[i])return-1;if(a[i]>b[i])return 1;}return n<m?-1:n>m;}static int reserve(struct file*f,u32 n){if(n<=f->content_capacity)return 1;u32 z=f->content_capacity;if(z<256)z=256;while(z<n){if(z>UINT32_MAX/2){z=n;break;}z*=2;}u8*p=heap_alloc(z);if(!p)return 0;cp(p,f->content,f->content_length);if(f->content&&!heap_free(f->content)){(void)heap_free(p);return 0;}f->content=p;f->content_capacity=z;return 1;}static int create(const u8*p,u32 n,const u8*d,u32 z){if(!file_path_valid(p,n)||file_count>=FILE_MAX_COUNT)return 0;u32 at=0;while(at<file_count){int q=cmp(files[at].path,files[at].path_length,p,n);if(!q)return 0;if(q>0)break;++at;}struct file f;f.path_length=(u16)n;f.content=0;f.content_length=f.content_capacity=f.attributes=0;cp(f.path,p,n);if(z){if(!reserve(&f,z))return 0;cp(f.content,d,z);f.content_length=z;}for(u32 i=file_count;i>at;--i)cpf(&files[i],&files[i-1]);cpf(&files[at],&f);++file_count;return 1;}static void discard(void){while(file_count){--file_count;if(files[file_count].content)(void)heap_free(files[file_count].content);}}int files_init(void){file_count=0;if(initial_file_count>FILE_MAX_COUNT)return 0;for(u32 i=0;i<initial_file_count;++i){const struct embedded_file*f=&initial_files[i];uintptr_t n=(uintptr_t)f->end-(uintptr_t)f->data;if(n>UINT32_MAX||!create(f->path,f->path_length,f->data,(u32)n)){discard();return 0;}}return 1;}u32 file_size(const struct file*f){return f->content_length;}const u8*file_content(const struct file*f){return f->content;}u32 file_attributes(const struct file*f){return f->attributes;}struct file*file_find(const u8*p,u32 n){for(u32 i=0;i<file_count;++i)if(eq(p,n,files[i].path,files[i].path_length))return&files[i];return 0;}int file_path_has_prefix(const struct file*f,const u8*p,u32 n){return n<=f->path_length&&eq(f->path,n,p,n);}static int resize(struct file*f,u32 n,int zero){u32 old=f->content_length;if(n==old)return 1;if(!n){if(f->content&&!heap_free(f->content))return 0;f->content=0;f->content_length=f->content_capacity=0;return 1;}if(!reserve(f,n))return 0;if(zero&&n>old)for(u32 i=old;i<n;++i)f->content[i]=0;f->content_length=n;return 1;}int file_write_span(const u8*p,u32 n,u32 off,u32 z,u8**out){struct file*f=file_find(p,n);if(!f){if(off||!create(p,n,0,0))return 0;f=file_find(p,n);}if(!f||(f->attributes&FILE_ATTRIBUTE_IMMUTABLE)||off>f->content_length||z>UINT32_MAX-off)return 0;if(z&&off+z>f->content_length&&!resize(f,off+z,0))return 0;*out=z?f->content+off:0;return 1;}int file_write(const u8*p,u32 n,u32 off,const u8*d,u32 z){u8*q;if(!file_write_span(p,n,off,z,&q))return 0;cp(q,d,z);return 1;}int file_truncate(const u8*p,u32 n,u32 z){struct file*f=file_find(p,n);return f&&!(f->attributes&FILE_ATTRIBUTE_IMMUTABLE)&&resize(f,z,1);}int file_remove(const u8*p,u32 n){struct file*f=file_find(p,n);if(!f||(f->attributes&FILE_ATTRIBUTE_IMMUTABLE))return 0;u32 at=(u32)(f-files);if(f->content&&!heap_free(f->content))return 0;for(u32 i=at;i+1<file_count;++i)cpf(&files[i],&files[i+1]);--file_count;return 1;}int file_seal(const u8*p,u32 n){struct file*f=file_find(p,n);if(!f)return 0;f->attributes|=FILE_ATTRIBUTE_IMMUTABLE;return 1;}
